.dm-shx{padding:12px;display:flex;flex-direction:column;gap:6px}
.dm-shx-h{display:flex;align-items:center;gap:10px;padding:2px 10px 8px}
.dm-shx-h>div{display:flex;flex-direction:column;min-width:0}
.dm-shx-h b{font-weight:500;font-size:13.5px}
.dm-shx-st{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-shx-list{display:flex;flex-direction:column}
.dm-shx-r{display:grid;grid-template-columns:28px minmax(0,1fr) auto;align-items:center;column-gap:12px;padding:8px 10px;border-radius:12px;font-size:13px;transition:background .2s}
@media (hover:hover) and (pointer:fine){.dm-shx-r:hover{background:var(--dm-row)}}
.dm-shx-r .dm-ic{width:28px;height:28px;border-radius:9px;display:grid;place-items:center;position:relative;align-self:center;transition:opacity .3s}
.dm-shx-r .dm-ic.dm-brandic{background:var(--dm-surface);box-shadow:inset 0 0 0 1px var(--dm-line);color:var(--dm-fg)}
.dm-shx-r .dm-ic .dm-brand{width:15px;height:15px}
.dm-shx-r .dm-ic::after{content:"";position:absolute;right:-2px;bottom:-2px;box-sizing:border-box;width:8px;height:8px;border-radius:50%;background:var(--dm-faint);box-shadow:0 0 0 2px var(--dm-surface);transition:background .3s}
.dm-shx-r[data-st="ok"] .dm-ic::after{background:var(--dm-ok)}
.dm-shx-r[data-st="bad"] .dm-ic::after{background:var(--dm-bad)}
.dm-shx-r[data-st="run"] .dm-ic::after{width:10px;height:10px;right:-3px;bottom:-3px;background:var(--dm-surface);border:1.5px solid var(--dm-accent-mark,var(--dm-accent));border-right-color:transparent;animation:dm-rot .8s linear infinite}
.dm-shx-r.dm-off .dm-ic::after{background:var(--dm-faint)}
/* the name shares its line with Run now and the switch; the schedule and the result below it take the full width */
.dm-shx-r .dm-ic{grid-row:1/4}
.dm-shx-r .dm-t{display:contents}
.dm-shx-r :is(.dm-nm,.dm-d,.dm-res){grid-column:2/-1;transition:color .3s}
.dm-shx-r .dm-nm{grid-column:2}
/* a paused one dims: its tile fades, and its name and result step down to muted, so the text stays readable */
.dm-shx-r.dm-off .dm-ic{opacity:.5}.dm-shx-r.dm-off :is(.dm-nm,.dm-res .dm-i){color:var(--dm-muted)}
.dm-shx-r .dm-nm,.dm-shx-r .dm-d{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-shx-r .dm-d{font-size:12px;color:var(--dm-muted)}
.dm-shx-r .dm-res{display:flex;align-items:center;gap:5px;min-width:0;height:18px;font-size:12px;color:var(--dm-muted)}
.dm-shx-r .dm-res>span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-shx-r .dm-res .dm-i{color:var(--dm-ok)}
.dm-shx-r[data-st="bad"] .dm-res,.dm-shx-r[data-st="bad"] .dm-res .dm-i{color:var(--dm-bad)}
.dm-shx-act{grid-column:3;grid-row:1;display:flex;align-items:center;gap:8px;margin-block:-5px}
.dm-shx-run{width:28px;height:28px}
.dm-shx-run:disabled{opacity:1;cursor:not-allowed;background:none;color:var(--dm-dis);transform:none}
.dm-shx-r .dm-shx-fx{grid-column:2/-1;grid-row:4}
.dm-shx-fx>div{overflow-clip-margin:0}
.dm-shx-fx>div>div{display:flex;flex-wrap:wrap;gap:6px;padding-top:8px}
.dm-shx-add{display:flex;align-items:center;gap:8px;height:30px;padding:0 12px 0 10px;font-size:12.5px;color:var(--dm-fg2);border-radius:var(--dm-r-pill);align-self:flex-start;transition:background-color .2s,color .2s}
@media (hover:hover) and (pointer:fine){.dm-shx-add:hover{color:var(--dm-fg);background:var(--dm-chip)}}
.dm-shx-pop{width:272px;padding:12px}
.dm-shx-f{display:flex;flex-direction:column;gap:8px}
.dm-shx-f h4{margin:0 0 2px;font-size:13px;font-weight:500}
.dm-shx-in{width:100%;height:32px;border:0;outline:0;border-radius:10px;background:var(--dm-chip);box-shadow:inset 0 0 0 1px var(--dm-field-line);padding:0 10px;font:inherit;font-size:13px;color:var(--dm-fg);transition:box-shadow .3s}
.dm-shx-in::placeholder{color:var(--dm-muted)}
.dm-shx-in:focus{box-shadow:inset 0 0 0 1px var(--dm-accent-mark,var(--dm-accent)),0 0 0 3px var(--dm-accent-bg)}
.dm-shx-rep{display:flex}
.dm-shx-rep button{flex:1 1 auto;padding:0 8px}
.dm-shx-days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px}
.dm-shx-days button{height:28px;border-radius:8px;background:var(--dm-chip);font-size:12px;color:var(--dm-fg2);transition:background .2s,color .2s}
@media (hover:hover) and (pointer:fine){.dm-shx-days button:hover{background:var(--dm-hover);color:var(--dm-fg)}}
.dm-shx-days button[aria-pressed="true"]{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
.dm-shx-ff{display:flex;align-items:center;gap:8px;padding-top:2px}
.dm-shx-sum{flex:1;min-width:0;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

